"""story/plan.py — the shot plan. Generates story/shots.json from timeline/sentences.json + words.json.
Each entry starts at a transcript sentence (0-based index; line N of transcript.txt = index N-1) and ends where the next one starts.
Run:  python3 story/plan.py   (from the project folder)
"""
import json, os, re

HERE = os.path.dirname(os.path.abspath(__file__)); PROJ = os.path.dirname(HERE)
SENT = json.load(open(os.path.join(PROJ, 'timeline/sentences.json')))
WORDS = json.load(open(os.path.join(PROJ, 'timeline/words.json')))['words']
DUR = 1206.5
LEAD = 0.15

def norm(w): return re.sub(r"[^\w']", '', w.lower())
def word_t(word, after, before):
    m = norm(word)
    for w in WORDS:
        if w['start'] >= after - 0.05 and w['start'] < before and norm(w['word']).startswith(m): return w['start']
    return None

PLAN = []
def add(i, tpl, scene, **p):
    extra = {k: p.pop(k) for k in ['tin', 'bars', 'sfx', 'amb', 'mb'] if k in p}
    PLAN.append(dict(i=i, scene=scene, params=dict(tpl=tpl, **p), **extra))
def c(who, x, pose='stand', expr='neutral', f=1, **kw): return dict(c=who, x=x, pose=pose, expr=expr, f=f, **kw)
def tx(s, at=None, **kw): d = dict(s=s, **kw); d['at'] = at; return d
def ro(label, value, at=None, **kw): return dict(label=label, value=value, at=at, **kw)
A = lambda i, set, cast, scene='', **p: add(i, 'act', scene, set=set, cast=cast, **p)
F = lambda i, who, expr, set, scene='', **p: add(i, 'face', scene, who=who, expr=expr, set=set, **p)
I = lambda i, obj, scene='', **p: add(i, 'ins', scene, obj=obj, **p)
C = lambda i, txt, set='void', scene='', **p: add(i, 'card', scene, txt=txt, set=set, **p)
PM = lambda i, kind, sub=None, set='class', **p: add(i, 'pm', f'{kind.upper()} card', kind=kind, sub=sub, set=set, **p)
B = lambda i, d, scene='', **p: add(i, 'bp', scene, d=d, bars='none', **p)
FACT = lambda i, kind, lines, **p: add(i, 'fact', f'{kind.upper()}: ' + ' / '.join(l['s'] for l in lines), kind=kind, lines=lines, bars='none', **p)
T3 = lambda i, s3, scene='', **p: add(i, '3d', scene, s3=s3, **p)
SFX = lambda *cues: [dict(zip(['at', 'name', 'gain'], q)) for q in cues]

