MUSIC = [(0, 70, 'playful', 0.4), (70, 132, 'wonder', 0.4), (132, 368, 'playful', 0.5), (368, 429, 'hopeful', 0.4), (429, 482, 'calm', 0.3), (482, 585, 'mystery', 0.45), (585, 694, 'sad', 0.35), (694, 762, 'dark', 0.4), (762, 896, 'tension', 0.7), (896, 920, 'epic', 0.9), (920, 1053, 'hopeful', 0.45), (1053, 1101, 'triumph', 0.5), (1101, 1161, 'wonder', 0.35), (1161, DUR, 'mystery', 0.5)]

def build():
    PLAN.sort(key=lambda e: e['i'])
    starts = []
    for k, e in enumerate(PLAN):
        st = 0.0 if k == 0 else round(max(SENT[e['i']]['start'] - LEAD, 0), 2)
        starts.append(st)
    shots = []
    for k, e in enumerate(PLAN):
        st, en = starts[k], (starts[k + 1] if k + 1 < len(PLAN) else DUR)
        assert en > st + 0.2, (e['i'], st, en)
        nxt_i = PLAN[k + 1]['i'] if k + 1 < len(PLAN) else len(SENT)
        line = ' '.join(s['text'] for s in SENT[e['i']:nxt_i])
        p = e['params']
        # python-safe keys -> js keys
        for f in p.get('fx2', []):
            for a, b in [('from_', 'from'), ('pass_', 'pass')]:
                if a in f: f[b] = f.pop(a)
        for a, b in [('from_', 'from')]:
            if a in p: p[b] = p.pop(a)
        if 'move' in p and 'from_' in p['move']: p['move']['from'] = p['move'].pop('from_')
        sfx = []
        for cue in e.get('sfx', []):
            at = cue['at']
            if isinstance(at, str) and at.startswith('w:'):
                wtm = word_t(at[2:], st - 0.25, en + 0.2)
                if wtm is None: print('  ! sfx word not found', at, 'in shot at', st); continue
                at = max(0, wtm - st - 0.03)
            sfx.append(dict(at=round(at, 2), name=cue['name'], gain=cue['gain']))
        shot = dict(id=f's{k + 1:03d}', start=st, end=round(en, 2), line=line, scene=e['scene'], set=p.get('set'), bars=e.get('bars'), **{'in': e.get('tin', {'type': 'cut'})}, sfx=sfx, params=p)
        AMB = dict(kitchen=('roomtone', -28), kitchenEve=('roomtone', -28), kitchenNight=('rain', -24), bedroom=('roomtone', -30), **{k: ('murmur', -30) for k in ['class', 'exam', 'chess', 'canteen']}, library=('roomtone', -30), gym=('murmur', -28), track=('murmur', -26), lab=('hum', -30), street=('city', -26), streetDusk=('city', -26), stage=('murmur', -30), hall=('murmur', -28))
        if 'amb' in e: shot['amb'] = e['amb']
        elif p.get('set') in AMB and p['tpl'] in ('act', 'face', 'ins', 'card', 'pm'): shot['amb'] = dict(name=AMB[p['set']][0], gain=AMB[p['set']][1])
        if e.get('mb'): shot['mb'] = e['mb']
        shots.append(shot)
    music = [dict(start=a, end=b, mood=m, intensity=x) for a, b, m, x in MUSIC]
    out = dict(title='What If You Could Think 10x Faster?', duration=DUR, shots=shots, music=music, sfx=[])
    json.dump(out, open(os.path.join(HERE, 'shots.json'), 'w'), indent=1, ensure_ascii=False)
    lens = sorted(s['end'] - s['start'] for s in shots)
    print(f'{len(shots)} shots, median {lens[len(lens)//2]:.2f}s, max {lens[-1]:.2f}s, min {lens[0]:.2f}s')

if __name__ == '__main__': build()
